-- Seeds the Gefährdungsradar questionnaire (Questionnaire + 44 Question rows),
-- bilingual (German default + English translation columns/keys).
-- Source: 2026-08-10_Fragebogen_Version 0.odt
--
-- The consent landing screen and the "already in Kulturkataster?" institution-link
-- screen are handled by the wizard's own hardcoded steps, not modeled as Question
-- rows here.
--
-- All questionnaire-scale questions are required. The final publication options
-- are intentionally optional checkboxes, because requiring both would force two
-- conflicting publication modes.
--
-- Seeded with status 'draft' so it doesn't go live automatically; flip
-- questionnaire.status to 'open' (e.g. via Prisma Studio) when ready.

WITH new_questionnaire AS (
	INSERT INTO questionnaire (title, title_en, description, description_en, status, meta_data, updated_at)
	SELECT 'Befragung zum Gefährdungsradar von Berliner Kulturorten', 'Survey on the Risk Radar for Berlin''s Cultural Venues', 'Wissenschaftliche Befragung zur Entwicklung des Kulturort-Index für Berliner Kultureinrichtungen.', 'Scientific survey for the development of the Cultural Venue Index for Berlin''s cultural institutions.', 'draft'::"QuestionnaireStatus", '{"blocks":{"1":{"title":"Block A: Standort und Vertragsdimension","title_en":"Block A: Location and Contract Dimension"},"2":{"title":"Block B: Immobilien- und Gebäudedimension","title_en":"Block B: Property and Building Dimension"},"3":{"title":"Block C: Finanz- und Betriebsdimension","title_en":"Block C: Financial and Operational Dimension"},"4":{"title":"Block D: Sozialräumliche und nachfragebezogene Dimension","title_en":"Block D: Socio-Spatial and Demand-Related Dimension"},"5":{"title":"Block E: Sichtbarkeits- und Öffentlichkeitsdimension","title_en":"Block E: Visibility and Public Relations Dimension"},"6":{"title":"Block F: Globale Einschätzungen","title_en":"Block F: Overall Assessment"},"7":{"title":"Einwilligung zur Datennutzung","title_en":"Consent to Data Use"}}}'::jsonb, NOW()
	WHERE NOT EXISTS (SELECT 1 FROM questionnaire WHERE title = 'Befragung zum Gefährdungsradar von Berliner Kulturorten')
	RETURNING id
)
INSERT INTO question (questionnaire_id, key, label, label_en, description, description_en, field_type, required, step, "order", config, updated_at)
SELECT nq.id, v.key, v.label, v.label_en, v.description, v.description_en, v.field_type, v.key NOT IN ('publish_named_consent', 'publish_anonymous_consent'), v.step, v.ord, v.config, NOW()
FROM new_questionnaire nq
CROSS JOIN (VALUES
	('room_usage', 'Wie nutzt Ihre Einrichtung die aktuell genutzten Räume?', 'How does your institution use its current premises?', NULL, NULL, 'radio', 1, 0, '{"options":[{"value":"ownership","label":"Eigentum","label_en":"Ownership"},{"value":"rent_regular","label":"reguläre Miete","label_en":"Regular rent"},{"value":"rent_sublet","label":"Untermiete","label_en":"Sublet"},{"value":"rent_temporary","label":"Zwischennutzung","label_en":"Temporary/interim use"},{"value":"rent_no_contract","label":"Nutzung ohne schriftlichen Vertrag","label_en":"Use without a written contract"},{"value":"rent_other","label":"Sonstiges","label_en":"Other"}],"freeTextOption":{"value":"rent_other","placeholder":"Bitte angeben","placeholder_en":"Please specify"}}'::jsonb),
	('rental_stability', 'Wie stabil schätzen Sie das Miet- bzw. Nutzungsverhältnis insgesamt ein?', 'How stable do you consider the rental or usage arrangement overall?', NULL, NULL, 'likert', 1, 1, '{"options":[{"value":"1","label":"sehr instabil","label_en":"very unstable"},{"value":"2","label":"eher instabil","label_en":"rather unstable"},{"value":"3","label":"teils/teils","label_en":"neutral"},{"value":"4","label":"eher stabil","label_en":"rather stable"},{"value":"5","label":"sehr stabil","label_en":"very stable"}]}'::jsonb),
	('ownership_change', 'Gab es in den letzten fünf Jahren einen Eigentümerwechsel des Gebäudes?', 'Has there been a change of ownership of the building in the last five years?', NULL, NULL, 'radio', 1, 2, '{"options":[{"value":"yes","label":"ja","label_en":"Yes"},{"value":"no","label":"nein","label_en":"No"},{"value":"unknown","label":"weiß ich nicht","label_en":"I don''t know"}],"condition":{"dependsOnKey":"room_usage","equals":["rent_regular","rent_sublet","rent_temporary","rent_no_contract","rent_other"]}}'::jsonb),
	('contract_remaining_term', 'Wie lang ist die Restlaufzeit Ihres aktuellen Miet- oder Nutzungsvertrags?', 'What is the remaining term of your current rental or usage contract?', NULL, NULL, 'radio', 1, 3, '{"options":[{"value":"no_written_contract","label":"kein schriftlicher Vertrag","label_en":"No written contract"},{"value":"contract_expired","label":"Mietvertrag abgelaufen","label_en":"Rental contract expired"},{"value":"under_6_months","label":"unter 6 Monate","label_en":"Less than 6 months"},{"value":"6_to_12_months","label":"6 bis unter 12 Monate","label_en":"6 to less than 12 months"},{"value":"1_to_2_years","label":"1 bis unter 2 Jahre","label_en":"1 to less than 2 years"},{"value":"2_to_5_years","label":"2 bis unter 5 Jahre","label_en":"2 to less than 5 years"},{"value":"5_years_or_more","label":"5 Jahre oder mehr","label_en":"5 years or more"},{"value":"unlimited","label":"Unbefristet","label_en":"Unlimited/indefinite"},{"value":"unknown","label":"nicht bekannt","label_en":"Not known"}],"condition":{"dependsOnKey":"room_usage","equals":["rent_regular","rent_sublet","rent_temporary","rent_no_contract","rent_other"]}}'::jsonb),
	('notice_period', 'Wie lang ist die reguläre Kündigungsfrist?', 'What is the regular notice period for termination?', NULL, NULL, 'radio', 1, 4, '{"options":[{"value":"no_contractual_notice_period","label":"keine vertraglich geregelte Kündigungsfrist","label_en":"No contractually defined notice period"},{"value":"under_3_months","label":"unter 3 Monate","label_en":"Less than 3 months"},{"value":"3_to_6_months","label":"3 bis unter 6 Monate","label_en":"3 to less than 6 months"},{"value":"6_to_12_months","label":"6 bis unter 12 Monate","label_en":"6 to less than 12 months"},{"value":"12_months_or_more","label":"12 Monate oder mehr","label_en":"12 months or more"},{"value":"unknown","label":"nicht bekannt","label_en":"Not known"}],"condition":{"dependsOnKey":"room_usage","equals":["rent_regular","rent_sublet","rent_temporary","rent_no_contract","rent_other"]}}'::jsonb),
	('eviction_notice', 'Liegt aktuell eine Kündigung, Räumungsandrohung oder Räumungsklage vor?', 'Is there currently a termination notice, eviction threat, or eviction lawsuit?', NULL, NULL, 'radio', 1, 5, '{"options":[{"value":"yes","label":"ja","label_en":"Yes"},{"value":"no","label":"nein","label_en":"No"},{"value":"unclear","label":"unklar","label_en":"Unclear"}],"condition":{"dependsOnKey":"room_usage","equals":["rent_regular","rent_sublet","rent_temporary","rent_no_contract","rent_other"]}}'::jsonb),
	('rent_model', 'Welches Mietmodell trifft auf Ihre Einrichtung zu?', 'Which rental model applies to your institution?', NULL, NULL, 'radio', 1, 6, '{"options":[{"value":"fixed_rent","label":"feste Miete","label_en":"Fixed rent"},{"value":"graduated_rent","label":"Staffelmiete","label_en":"Graduated rent"},{"value":"index_rent","label":"Indexmiete","label_en":"Index-linked rent"},{"value":"usage_based_rent","label":"nutzungsabhängige Miete","label_en":"Usage-based rent"},{"value":"no_regular_rental","label":"kein reguläres Mietverhältnis","label_en":"No regular rental arrangement"},{"value":"unknown","label":"nicht bekannt","label_en":"Not known"}],"condition":{"dependsOnKey":"room_usage","equals":["rent_regular","rent_sublet","rent_temporary","rent_no_contract","rent_other"]}}'::jsonb),
	('rent_development', 'Wie hat sich die Miethöhe in den letzten drei Jahren entwickelt?', 'How has the rent level developed over the past three years?', NULL, NULL, 'likert', 1, 7, '{"options":[{"value":"1","label":"stark gesunken","label_en":"Decreased significantly"},{"value":"2","label":"leicht gesunken","label_en":"Decreased slightly"},{"value":"3","label":"gleichgeblieben","label_en":"Stayed the same"},{"value":"4","label":"leicht gestiegen","label_en":"Increased slightly"},{"value":"5","label":"stark gestiegen","label_en":"Increased significantly"},{"value":"6","label":"nicht bekannt","label_en":"Not known"}],"condition":{"dependsOnKey":"room_usage","equals":["rent_regular","rent_sublet","rent_temporary","rent_no_contract","rent_other"]}}'::jsonb),
	('location_dependency', 'Wie stark ist Ihre Einrichtung auf den aktuellen Standort angewiesen, weil realistische Ausweichoptionen fehlen?', 'How dependent is your institution on its current location due to a lack of realistic alternative options?', NULL, NULL, 'likert', 1, 8, '{"options":[{"value":"1","label":"gar nicht","label_en":"Not at all"},{"value":"2","label":"eher wenig","label_en":"Rather little"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher stark","label_en":"Rather strongly"},{"value":"5","label":"sehr stark","label_en":"Very strongly"}]}'::jsonb),
	('building_condition', 'Wie bewerten Sie den baulichen Zustand des Gebäudes insgesamt?', 'How do you rate the overall structural condition of the building?', NULL, NULL, 'likert', 2, 0, '{"options":[{"value":"1","label":"sehr gut","label_en":"Very good"},{"value":"2","label":"eher gut","label_en":"Rather good"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher schlecht","label_en":"Rather poor"},{"value":"5","label":"sehr schlecht","label_en":"Very poor"}]}'::jsonb),
	('building_construction_period', 'In welchem Zeitraum wurde das Gebäude überwiegend errichtet?', 'In which period was the building predominantly constructed?', NULL, NULL, 'radio', 2, 1, '{"options":[{"value":"before_1900","label":"vor 1900","label_en":"Before 1900"},{"value":"1900_1945","label":"1900–1945","label_en":"1900–1945"},{"value":"1946_1979","label":"1946–1979","label_en":"1946–1979"},{"value":"1980_1999","label":"1980–1999","label_en":"1980–1999"},{"value":"2000_or_later","label":"2000 oder später","label_en":"2000 or later"},{"value":"unknown","label":"nicht bekannt","label_en":"Not known"}]}'::jsonb),
	('room_suitability', 'Wie gut sind die Räume für den aktuellen Betrieb geeignet? (z.B. Größe, Zuschnitt, Ausstattung, Nutzbarkeit etc.)', 'How well suited are the premises for current operations? (e.g. size, layout, equipment, usability, etc.)', NULL, NULL, 'likert', 2, 2, '{"options":[{"value":"1","label":"sehr gut geeignet","label_en":"Very well suited"},{"value":"2","label":"eher gut geeignet","label_en":"Rather well suited"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher ungeeignet","label_en":"Rather unsuited"},{"value":"5","label":"sehr ungeeignet","label_en":"Very unsuited"}]}'::jsonb),
	('renovation_pressure', 'Gibt es aktuell Sanierungsdruck oder erheblichen Modernisierungsbedarf im Gebäude?', 'Is there currently pressure for renovation or a significant need for modernization in the building?', NULL, NULL, 'likert', 2, 3, '{"options":[{"value":"yes_high","label":"ja, in hohem Maß","label_en":"Yes, to a high degree"},{"value":"yes_partially","label":"ja, teilweise","label_en":"Yes, partially"},{"value":"no","label":"nein","label_en":"No"},{"value":"unknown","label":"nicht bekannt","label_en":"Not known"}]}'::jsonb),
	('alternative_use_planned', 'Sind Ihnen Hinweise bekannt, dass eine andere Nutzung für Ihr Gebäude oder Grundstück geplant sein könnte?', 'Are you aware of any indications that a different use for your building or property might be planned?', NULL, NULL, 'radio', 2, 4, '{"options":[{"value":"yes_specify","label":"ja, folgende","label_en":"Yes, namely"},{"value":"no","label":"nein","label_en":"No"},{"value":"unclear","label":"unklar","label_en":"Unclear"}],"freeTextOption":{"value":"yes_specify","placeholder":"Bitte angeben","placeholder_en":"Please specify"}}'::jsonb),
	('nearby_construction_projects', 'Sind Ihnen geplante Bauprojekte im unmittelbaren Umfeld bekannt, die den Standort Ihrer Einrichtung negativ beeinflussen könnten?', 'Are you aware of any planned construction projects in the immediate vicinity that could negatively affect your institution''s location?', NULL, NULL, 'radio', 2, 5, '{"options":[{"value":"yes_specify","label":"Ja, folgende","label_en":"Yes, namely"},{"value":"no","label":"nein","label_en":"No"},{"value":"cannot_assess","label":"kann ich nicht beurteilen","label_en":"I cannot assess this"}],"freeTextOption":{"value":"yes_specify","placeholder":"Bitte angeben","placeholder_en":"Please specify"}}'::jsonb),
	('zoning_changes_known', 'Sind Ihnen geplante oder mögliche Nutzungsänderungen im planungsrechtlichen Umfeld bekannt, die Auswirkungen auf Ihre Einrichtung haben könnten?', 'Are you aware of any planned or possible zoning/land-use changes in the surrounding planning context that could affect your institution?', NULL, NULL, 'radio', 2, 6, '{"options":[{"value":"yes_specify","label":"Ja, folgende","label_en":"Yes, namely"},{"value":"no","label":"nein","label_en":"No"},{"value":"cannot_assess","label":"kann ich nicht beurteilen","label_en":"I cannot assess this"}],"freeTextOption":{"value":"yes_specify","placeholder":"Bitte angeben","placeholder_en":"Please specify"}}'::jsonb),
	('funding_type', 'Welche Form öffentlicher Förderung erhält Ihre Einrichtung derzeit überwiegend?', 'What form of public funding does your institution predominantly currently receive?', NULL, NULL, 'radio', 3, 0, '{"options":[{"value":"none","label":"keine öffentliche Förderung","label_en":"No public funding"},{"value":"mostly_project_based","label":"überwiegend projektbezogene Förderung","label_en":"Predominantly project-based funding"},{"value":"mostly_institutional","label":"überwiegend institutionelle Förderung","label_en":"Predominantly institutional funding"},{"value":"mixed","label":"etwa gleichmäßige Mischförderung","label_en":"Roughly equal mixed funding"},{"value":"other","label":"sonstige Form","label_en":"Other form"}],"freeTextOption":{"value":"other","placeholder":"Bitte angeben","placeholder_en":"Please specify"}}'::jsonb),
	('funding_security', 'Wie würden Sie die aktuelle Fördersituation Ihrer Einrichtung insgesamt bewerten?', 'How would you rate your institution''s current funding situation overall?', NULL, NULL, 'likert', 3, 1, '{"options":[{"value":"1","label":"sehr unsicher","label_en":"Very insecure"},{"value":"2","label":"eher unsicher","label_en":"Rather insecure"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher gesichert","label_en":"Rather secure"},{"value":"5","label":"sehr sicher","label_en":"Very secure"}]}'::jsonb),
	('funding_source_importance', 'Bitte schätzen Sie die Bedeutung Ihrer Finanzierungsquellen grob ein.', 'Please roughly estimate the importance of your funding sources.', NULL, NULL, 'likertMatrix', 3, 2, '{"options":[{"value":"1","label":"keine Bedeutung","label_en":"No importance"},{"value":"2","label":"eher nicht so hohe Bedeutung","label_en":"Rather low importance"},{"value":"3","label":"mittlere Bedeutung","label_en":"Medium importance"},{"value":"4","label":"eher hohe Bedeutung","label_en":"Rather high importance"},{"value":"5","label":"hohe Bedeutung","label_en":"High importance"}],"likertMatrix":{"rows":[{"key":"public_funding","label":"öffentliche Förderung","label_en":"Public funding"},{"key":"own_income","label":"Eigeneinnahmen","label_en":"Own income"},{"key":"donations","label":"Spenden","label_en":"Donations"},{"key":"sponsoring","label":"Sponsoring","label_en":"Sponsorship"},{"key":"reserves","label":"Finanzielle Rücklagen","label_en":"Financial reserves"},{"key":"other_income","label":"sonstige Einnahmen","label_en":"Other income"}]}}'::jsonb),
	('funder_dependency', 'Wie stark ist Ihre Einrichtung von Fördermittelgebern abhängig?', 'How dependent is your institution on funding providers?', NULL, NULL, 'likert', 3, 3, '{"options":[{"value":"1","label":"gar nicht","label_en":"Not at all"},{"value":"2","label":"eher wenig","label_en":"Rather little"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher stark","label_en":"Rather strongly"},{"value":"5","label":"sehr stark","label_en":"Very strongly"}]}'::jsonb),
	('financial_situation_trend', 'Wie hat sich die finanzielle Situation Ihrer Einrichtung in den letzten drei Jahren entwickelt?', 'How has your institution''s financial situation developed over the past three years?', NULL, NULL, 'likert', 3, 4, '{"options":[{"value":"1","label":"deutlich verschlechtert","label_en":"Deteriorated significantly"},{"value":"2","label":"eher verschlechtert","label_en":"Deteriorated somewhat"},{"value":"3","label":"gleichgeblieben","label_en":"Stayed the same"},{"value":"4","label":"eher verbessert","label_en":"Improved somewhat"},{"value":"5","label":"deutlich verbessert","label_en":"Improved significantly"}]}'::jsonb),
	('financial_situation_current', 'Wie bewerten Sie die aktuelle finanzielle Situation Ihrer Einrichtung insgesamt?', 'How do you rate your institution''s current financial situation overall?', NULL, NULL, 'likert', 3, 5, '{"options":[{"value":"1","label":"sehr schlecht","label_en":"Very poor"},{"value":"2","label":"eher schlecht","label_en":"Rather poor"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher gut","label_en":"Rather good"},{"value":"5","label":"sehr gut","label_en":"Very good"}]}'::jsonb),
	('financial_outlook', 'Wie schätzen Sie die finanzielle Entwicklung Ihrer Einrichtung in den nächsten drei Jahren ein?', 'How do you assess your institution''s financial development over the next three years?', NULL, NULL, 'likert', 3, 6, '{"options":[{"value":"1","label":"sehr negativ","label_en":"Very negative"},{"value":"2","label":"eher negativ","label_en":"Rather negative"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher positiv","label_en":"Rather positive"},{"value":"5","label":"sehr positiv","label_en":"Very positive"}]}'::jsonb),
	('staffing_level', 'Wie bewerten Sie die personelle Ausstattung Ihrer Einrichtung insgesamt?', 'How do you rate your institution''s staffing levels overall?', NULL, NULL, 'likert', 3, 7, '{"options":[{"value":"1","label":"sehr unzureichend","label_en":"Very insufficient"},{"value":"2","label":"eher unzureichend","label_en":"Rather insufficient"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher ausreichend","label_en":"Rather sufficient"},{"value":"5","label":"sehr ausreichend","label_en":"Very sufficient"}]}'::jsonb),
	('key_person_dependency', 'Wie stark hängt der laufende Betrieb von einzelnen Schlüsselpersonen ab?', 'How dependent is day-to-day operation on individual key persons?', NULL, NULL, 'likert', 3, 8, '{"options":[{"value":"1","label":"gar nicht","label_en":"Not at all"},{"value":"2","label":"eher wenig","label_en":"Rather little"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher stark","label_en":"Rather strongly"},{"value":"5","label":"sehr stark","label_en":"Very strongly"}]}'::jsonb),
	('usage_trend', 'Wie hat sich der Umfang der Nutzung Ihrer Einrichtung in den letzten drei Jahren insgesamt entwickelt? Bitte beziehen Sie sich auf die für Ihre Einrichtung passende Form der Nutzung (z.B. Besucher:innenzahlen, Teilnehmendenzahlen, Buchungen, Belegungstage oder Raumnutzungen)', 'How has the overall extent of use of your institution developed over the past three years? Please refer to whichever form of usage best fits your institution (e.g. visitor numbers, participant numbers, bookings, occupancy days, or room usage).', NULL, NULL, 'likert', 4, 0, '{"options":[{"value":"1","label":"deutlich zurückgegangen","label_en":"Decreased significantly"},{"value":"2","label":"eher zurückgegangen","label_en":"Decreased somewhat"},{"value":"3","label":"weitgehend gleichgeblieben","label_en":"Largely stayed the same"},{"value":"4","label":"eher gestiegen","label_en":"Increased somewhat"},{"value":"5","label":"deutlich gestiegen","label_en":"Increased significantly"},{"value":"6","label":"kann nicht eingeschätzt werden","label_en":"Cannot be assessed"}]}'::jsonb),
	('capacity_utilization_trend', 'Wie hat sich die Auslastung der verfügbaren Kapazitäten Ihrer Einrichtung in den letzten drei Jahren insgesamt entwickelt? Gemeint ist das Verhältnis zwischen der tatsächlichen Nutzung und den verfügbaren räumlichen, zeitlichen oder personellen Kapazitäten.', 'How has the utilization of your institution''s available capacity developed over the past three years overall? This refers to the ratio between actual use and available spatial, temporal, or staffing capacity.', NULL, NULL, 'likert', 4, 1, '{"options":[{"value":"1","label":"deutlich zurückgegangen","label_en":"Decreased significantly"},{"value":"2","label":"eher zurückgegangen","label_en":"Decreased somewhat"},{"value":"3","label":"weitgehend gleichgeblieben","label_en":"Largely stayed the same"},{"value":"4","label":"eher gestiegen","label_en":"Increased somewhat"},{"value":"5","label":"deutlich gestiegen","label_en":"Increased significantly"},{"value":"6","label":"kann nicht eingeschätzt werden","label_en":"Cannot be assessed"},{"value":"7","label":"für unsere Einrichtung nicht sinnvoll beurteilbar","label_en":"Not meaningfully assessable for our institution"}]}'::jsonb),
	('accessibility', 'Wie barrierefrei bzw. barrierearm ist Ihre Einrichtung nach Ihrer Einschätzung erreichbar und nutzbar?', 'In your assessment, how accessible (barrier-free or low-barrier) is your institution to reach and use?', NULL, NULL, 'likert', 4, 2, '{"options":[{"value":"1","label":"gar nicht","label_en":"Not at all"},{"value":"2","label":"eher wenig","label_en":"Rather little"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher gut","label_en":"Rather well"},{"value":"5","label":"sehr gut","label_en":"Very well"}]}'::jsonb),
	('location_quality', 'Wie bewerten Sie die räumliche Lage (z.B. allgemeine Erreichbarkeit; Lage im Stadtgebiet, Nähe zu Zielgruppen) Ihrer Einrichtung insgesamt?', 'How do you rate the spatial location of your institution overall (e.g. general accessibility, location within the city, proximity to target groups)?', NULL, NULL, 'likert', 4, 3, '{"options":[{"value":"1","label":"sehr ungünstig","label_en":"Very unfavorable"},{"value":"2","label":"eher ungünstig","label_en":"Rather unfavorable"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher günstig","label_en":"Rather favorable"},{"value":"5","label":"sehr günstig","label_en":"Very favorable"}]}'::jsonb),
	('competition_impact', 'In welchem Maß beeinträchtigt die Konkurrenz durch ähnliche Angebote die Nutzung oder wirtschaftliche Situation Ihrer Einrichtung?', 'To what extent does competition from similar offerings affect the use or economic situation of your institution?', NULL, NULL, 'likert', 4, 4, '{"options":[{"value":"1","label":"gar nicht","label_en":"Not at all"},{"value":"2","label":"eher wenig","label_en":"Rather little"},{"value":"3","label":"teilweise","label_en":"Partially"},{"value":"4","label":"eher stark","label_en":"Rather strongly"},{"value":"5","label":"sehr stark","label_en":"Very strongly"},{"value":"6","label":"ähnliche Angebote werden nicht als Konkurrenz wahrgenommen","label_en":"Similar offerings are not perceived as competition"}]}'::jsonb),
	('neighborhood_integration', 'Wie gut ist Ihre Einrichtung in die Nachbarschaft und das kulturelle Umfeld eingebunden?', 'How well is your institution integrated into the neighborhood and cultural environment?', NULL, NULL, 'likert', 4, 5, '{"options":[{"value":"1","label":"gar nicht","label_en":"Not at all"},{"value":"2","label":"eher schwach","label_en":"Rather weakly"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher gut","label_en":"Rather well"},{"value":"5","label":"sehr gut","label_en":"Very well"},{"value":"6","label":"für unsere Einrichtung nicht relevant bzw. nicht beurteilbar","label_en":"Not relevant or assessable for our institution"}]}'::jsonb),
	('community_relation_importance', 'Wie wichtig ist der aktuelle Standort für die Beziehung Ihrer Einrichtung zur lokalen Community bzw. zum unmittelbaren Umfeld?', 'How important is the current location for your institution''s relationship with the local community or immediate surroundings?', NULL, NULL, 'likert', 4, 6, '{"options":[{"value":"1","label":"gar nicht wichtig","label_en":"Not important at all"},{"value":"2","label":"eher wenig wichtig","label_en":"Rather unimportant"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher wichtig","label_en":"Rather important"},{"value":"5","label":"sehr wichtig","label_en":"Very important"},{"value":"6","label":"für unsere Einrichtung nicht relevant bzw. nicht beurteilbar","label_en":"Not relevant or assessable for our institution"}]}'::jsonb),
	('neighborhood_conflicts_frequency', 'Wie häufig treten Nachbarschaftskonflikte oder standortbezogene Konflikte (z.B. Beschwerden wegen Lärmbelästigung) mit dem Umfeld auf?', 'How often do neighborhood conflicts or location-related conflicts (e.g. noise complaints) with the surrounding area occur?', NULL, NULL, 'likert', 4, 7, '{"options":[{"value":"1","label":"nie","label_en":"Never"},{"value":"2","label":"selten","label_en":"Rarely"},{"value":"3","label":"gelegentlich","label_en":"Occasionally"},{"value":"4","label":"häufig","label_en":"Frequently"},{"value":"5","label":"sehr häufig","label_en":"Very frequently"}]}'::jsonb),
	('online_findability', 'Wie gut ist Ihre Einrichtung nach Ihrer Einschätzung im Internet auffindbar?', 'In your assessment, how easily can your institution be found online?', NULL, NULL, 'likert', 5, 0, '{"options":[{"value":"1","label":"gar nicht","label_en":"Not at all"},{"value":"2","label":"eher schlecht","label_en":"Rather poorly"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher gut","label_en":"Rather well"},{"value":"5","label":"sehr gut","label_en":"Very well"}]}'::jsonb),
	('web_presence_freshness', 'Wie aktuell ist die Webpräsenz Ihrer Einrichtung in der Regel?', 'How up to date is your institution''s web presence generally?', NULL, NULL, 'likert', 5, 1, '{"options":[{"value":"1","label":"sehr selten aktuell","label_en":"Very rarely up to date"},{"value":"2","label":"eher selten aktuell","label_en":"Rather rarely up to date"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher aktuell","label_en":"Rather up to date"},{"value":"5","label":"sehr aktuell","label_en":"Very up to date"},{"value":"6","label":"keine eigene Webpräsenz","label_en":"No own web presence"}]}'::jsonb),
	('event_info_reliability', 'Wie zuverlässig sind aktuelle Veranstaltungs- oder Nutzungsinformationen online verfügbar?', 'How reliably is current event or usage information available online?', NULL, NULL, 'likert', 5, 2, '{"options":[{"value":"1","label":"gar nicht zuverlässig","label_en":"Not reliable at all"},{"value":"2","label":"eher unzuverlässig","label_en":"Rather unreliable"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher zuverlässig","label_en":"Rather reliable"},{"value":"5","label":"sehr zuverlässig","label_en":"Very reliable"},{"value":"6","label":"nicht zutreffend","label_en":"Not applicable"}]}'::jsonb),
	('digital_channels', 'Auf welchen digitalen Kanälen oder Plattformen ist Ihre Einrichtung aktiv präsent (Aktivitäten innerhalb der letzten 3 Monate)?', 'On which digital channels or platforms is your institution actively present (activity within the last 3 months)?', NULL, NULL, 'multiselect', 5, 3, '{"options":[{"value":"website","label":"eigene Webseite","label_en":"Own website"},{"value":"newsletter","label":"E-Mail-Newsletter","label_en":"Email newsletter"},{"value":"social_networks","label":"Soziale Netzwerke (z.B. Instagram, TikTok, Facebook, Twitter)","label_en":"Social networks (e.g. Instagram, TikTok, Facebook, Twitter)"},{"value":"video_platforms","label":"Videoplattformen (z.B. YouTube)","label_en":"Video platforms (e.g. YouTube)"},{"value":"linkedin","label":"LinkedIn","label_en":"LinkedIn"},{"value":"messengers","label":"Messenger-Kanäle (z.B. WhatsApp)","label_en":"Messenger channels (e.g. WhatsApp)"},{"value":"event_culture_platforms","label":"Veranstaltungs- und Kulturplattformen (z.B. VisitBerlin)","label_en":"Event and culture platforms (e.g. VisitBerlin)"},{"value":"ticketing_platforms","label":"Ticketingplattformen (z.B. Eventim)","label_en":"Ticketing platforms (e.g. Eventim)"},{"value":"other","label":"Sonstige","label_en":"Other"},{"value":"none","label":"auf keinen digitalen Kanälen aktiv","label_en":"Not active on any digital channels"}],"freeTextOption":{"value":"other","placeholder":"Bitte angeben","placeholder_en":"Please specify"}}'::jsonb),
	('visibility_resources', 'Wie ausreichend sind die personellen oder zeitlichen Ressourcen für digitale Sichtbarkeit und Öffentlichkeitsarbeit?', 'How sufficient are the staffing or time resources for digital visibility and public relations work?', NULL, NULL, 'likert', 5, 4, '{"options":[{"value":"1","label":"gar nicht ausreichend","label_en":"Not sufficient at all"},{"value":"2","label":"eher nicht ausreichend","label_en":"Rather insufficient"},{"value":"3","label":"teils/teils","label_en":"Neutral"},{"value":"4","label":"eher ausreichend","label_en":"Rather sufficient"},{"value":"5","label":"sehr ausreichend","label_en":"Very sufficient"}]}'::jsonb),
	('future_risk', 'Wie gefährdet schätzen Sie die Zukunft Ihrer Einrichtung am aktuellen Standort insgesamt ein?', 'How at risk do you consider your institution''s future at its current location overall?', NULL, NULL, 'likert', 6, 0, '{"options":[{"value":"1","label":"überhaupt nicht gefährdet","label_en":"Not at risk at all"},{"value":"2","label":"eher wenig gefährdet","label_en":"Rather slightly at risk"},{"value":"3","label":"mittelmäßig gefährdet","label_en":"Moderately at risk"},{"value":"4","label":"eher stark gefährdet","label_en":"Rather strongly at risk"},{"value":"5","label":"sehr stark gefährdet","label_en":"Very strongly at risk"}]}'::jsonb),
	('location_loss_probability', 'Wie wahrscheinlich ist es, dass Ihre Einrichtung in den nächsten zwei Jahren ihren aktuellen Standort verliert?', 'How likely is it that your institution will lose its current location within the next two years?', NULL, NULL, 'likert', 6, 1, '{"options":[{"value":"1","label":"sehr unwahrscheinlich","label_en":"Very unlikely"},{"value":"2","label":"eher unwahrscheinlich","label_en":"Rather unlikely"},{"value":"3","label":"unklar","label_en":"Unclear"},{"value":"4","label":"eher wahrscheinlich","label_en":"Rather likely"},{"value":"5","label":"sehr wahrscheinlich","label_en":"Very likely"}]}'::jsonb),
	('operation_reduction_probability', 'Wie wahrscheinlich ist es, dass Ihre Einrichtung in den nächsten zwei Jahren ihren Betrieb oder ihr Angebot wesentlich einschränken muss?', 'How likely is it that your institution will have to significantly reduce its operations or offerings within the next two years?', NULL, NULL, 'likert', 6, 2, '{"options":[{"value":"1","label":"sehr unwahrscheinlich","label_en":"Very unlikely"},{"value":"2","label":"eher unwahrscheinlich","label_en":"Rather unlikely"},{"value":"3","label":"unklar","label_en":"Unclear"},{"value":"4","label":"eher wahrscheinlich","label_en":"Rather likely"},{"value":"5","label":"sehr wahrscheinlich","label_en":"Very likely"}]}'::jsonb),
	('priority_area', 'In welchem Bereich sehen Sie derzeit den größten Handlungsbedarf?', 'In which area do you currently see the greatest need for action?', NULL, NULL, 'radio', 6, 3, '{"options":[{"value":"location_contract","label":"Standort/Vertrag","label_en":"Location/Contract"},{"value":"building","label":"Gebäude","label_en":"Building"},{"value":"finance_funding","label":"Finanzen/Förderung","label_en":"Finance/Funding"},{"value":"organization_staff","label":"Organisation/Personal","label_en":"Organization/Staff"},{"value":"demand_environment","label":"Nachfrage/Umfeld","label_en":"Demand/Environment"},{"value":"visibility_public","label":"Sichtbarkeit/Öffentlichkeit","label_en":"Visibility/Public relations"},{"value":"other","label":"Sonstiges","label_en":"Other"}],"freeTextOption":{"value":"other","placeholder":"Bitte angeben","placeholder_en":"Please specify"}}'::jsonb),
